def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    table = {
        ((1,1,1),(1,1,1)): 5,
        ((0,1,0),(1,1,1),(0,1,0)): 3,
        ((1,1,0),(0,1,1)): 8,
        ((1,),(1,),(1,)): 2,
        ((1,1),(0,1)): 4,
        ((1,),(1,)): 9,
    }
    size_fallback = {}
    for k, v in table.items():
        s = int(np.array(k).sum())
        size_fallback.setdefault(s, v)
    for o in objects(g, bg=bg):
        key = tuple(map(tuple, (o["grid"] != bg).astype(int)))
        col = table.get(key, size_fallback.get(o["size"]))
        if col is None:
            continue
        for (y, x) in o["cells"]:
            out[y, x] = col
        emit(out, f"Recolour the size-{o['size']} object at box {o['box']} to colour {col} according to its shape.")
    emit(out, "All grey shapes recoloured by their shape.")
    return out
